  TOO_FEW_COMPETITOR_OFFERS: 'Trop peu d’offres concurrentes',
  HISTORY_TOO_SHORT: 'Historique des prix trop court',
  HISTORY_AVAILABLE: 'Historique des prix disponible',
  NO_SCALE_REFERENCE: 'Rien pour contrôler l’ordre de grandeur',
  SINGLE_SELLER_MARKET_EVENT: 'Un seul vendeur a bougé',
  DISPERSED_MARKET_EVENT: 'Le marché a bougé de façon inégale',
  SHIFT_BELOW_SHARE: 'Trop peu de produits ont bougé pour une suspension',
  SMALL_MOVE: 'Faible mouvement',
  NO_PREVIOUS_SNAPSHOT: 'Pas de données de la concurrence précédentes',
