/**
 * Шаг 68 (K11): причина стратегии, у которой суммы конкурента в объяснении уже не хранятся [Р-85]. Горячее намерение держит их
 * 3 дня, и «почему эта цена» берёт суммы оттуда; у решения старше — этот текст вместо заглушки на месте каждой суммы
 */
const keptNote = 'La décision ne conserve les montants tirés des prix concurrents que 3 jours ; ils ne sont donc plus affichés. Les données de la concurrence complètes restent accessibles par le lien de leur étape.';
/** Подрез — параметр стратегии: известен, пока его версия в справочнике (18 месяцев после замены, Р-91) */
const step = (f: Fmt) => (typeof f.get('undercutMinor') === 'number' ? f.money('undercutMinor') : 'l’écart défini par la stratégie');
const reasonsWithoutChannel: Partial<Record<AnyReasonCode | SanityNoteCode, Template>> = {
  // Ревью шага 68, находка 4: суммы из цены конкурента решение держит 3 суток [Р-28]; сам снимок — 18 месяцев по ссылке шага снимка
  BUYBOX_MATCH: () => `Aligné sur le prix de la Buy Box observé à ce moment. ${keptNote}`,
  BUYBOX_UNDERCUT: (f) => `Passé sous le prix de la Buy Box observé à ce moment, de ${step(f)}. ${keptNote}`,
  LOWEST_MATCH: (f) => `Aligné sur le prix le plus bas ${f.get('scope') === 'MARKET' ? 'du marché' : 'parmi les offres visibles'} observé à ce moment. ${keptNote}`,
  LOWEST_UNDERCUT: (f) => `Passé sous le prix le plus bas observé à ce moment, de ${step(f)}. ${keptNote}`,
  // Шаг 97: цель «Win the Buy Box» и цена, на которой Buy Box ушёл, выведены из данных канала [Р-85]
  BUYBOX_WIN_TARGET: (f) => `Passé sous le prix livraison comprise du gagnant de la Buy Box observé à ce moment, de ${step(f)}. ${keptNote}`,
  CREEP_STEP_BACK: (f) => `La Buy Box a été perdue juste après une hausse — retour à ${f.money('backToMinor')}, le dernier prix qui la détenait ; hausses en pause jusqu’à ${f.when('pausedUntil')}.`,
  CAPPED_AT_CREEP_CEILING: () => 'Pendant la pause des hausses, la cible a été maintenue sous le prix auquel la Buy Box a été perdue.',
  BUYBOX_HOLDER_UNKNOWN: (f) => `Ce canal n’indique pas qui détient la Buy Box ; votre prix ${f.money('currentMinor')} était égal au prix de la Buy Box, elle était donc peut-être à vous — le prix est resté inchangé.`,
  /**
   * Заметки и предупреждения проверки входов: их числа (сколько предложений, дней истории, какой продавец) — данные канала, и их нет ни
   * в вечном объяснении, ни в горячем намерении. Текст называет правило и его порог, а не пустое место
   */
  TOO_FEW_COMPETITOR_OFFERS: (f) => `moins d’offres concurrentes que les ${f.count('minOffers')} requises`,
  HISTORY_TOO_SHORT: (f) => `moins d’historique des prix que les ${f.count('minHistoryDays')} jours requis`,
  HISTORY_AVAILABLE: () => 'assez d’historique des prix pour contrôler',
  SINGLE_SELLER_MARKET_EVENT: () => 'un seul vendeur a bougé — mouvement de marché',
  DISPERSED_MARKET_EVENT: (f) => `facteurs différents (dispersion au-dessus de ${f.ratio('maxSpread')}) — mouvement de marché`,
  SHIFT_BELOW_SHARE: (f) => `moins de produits ont bougé qu’il n’en faut pour une suspension (${f.count('minProducts')} et une part de ${f.ratio('share')})`,
  NO_PLAUSIBILITY_ANCHOR: (f) => `Données de la concurrence non utilisées : aucun repère pour les contrôler (coût unitaire ${f.get('costDeclared') ? 'déclaré' : 'manquant'}). Déclarez le coût unitaire — c’est le repère principal.`,
  OWN_PRICE_DEVIATION: (f) => `Avertissement : ${f.value('field')} s’écartait de notre prix ${f.money('ourPriceMinor')} de plus de ${f.ratio('limit')} ; les données de la concurrence ont été acceptées.`,
  SELF_OFFER_DIVERGENCE: (f) => `Notre offre affichait sur le canal un autre prix que notre prix ${f.money('ourPriceMinor')} — un dossier d’écart a été ouvert.`,
  INTERNAL_OUTLIER_IGNORED: () => 'Avertissement : une offre était loin de la médiane des données de la concurrence, mais la stratégie ne l’utilise pas.',
  MARKET_SHIFT_DISPERSED: () => 'Mouvement de marché : les produits ont évolué avec des facteurs différents ; la tarification continue normalement.',
  MARKET_SHIFT_SINGLE_SELLER: () => 'Mouvement de marché : un seul vendeur a modifié les prix de plusieurs produits ; la tarification continue normalement.',
  // Цель стратегии выведена из цены конкурента [Р-85]: граница и решение — наши, их сумма остаётся
  CAPPED_AT_MIN_PRICE: (f) => `La cible issue des prix concurrents était sous votre prix minimum — ramenée à ${f.money('minMinor')}.`,
  CAPPED_AT_MAX_PRICE: (f) => `La cible issue des prix concurrents dépassait votre prix maximum — ramenée à ${f.money('maxMinor')}.`,
  CAPPED_AT_MARGIN_FLOOR: (f) => `La cible issue des prix concurrents était sous votre plancher de marge — fixée au plancher de marge ${f.money('floorMinor')} (marge ${f.bp('minMarginBp')}).`,
  ALREADY_AT_TARGET: () => 'Le prix était déjà égal à la cible.',
  WITHIN_DEADBAND: (f) => `L’écart avec la cible était sous le seuil de ${f.money('deadbandMinor')} — le prix reste inchangé.`,
  TARGET_OUTSIDE_BOUNDS_HOLD: (f) => `La cible était hors de ${f.money('minMinor')}–${f.money('maxMinor')} ; la stratégie est réglée pour maintenir le prix.`,
  COMPETITOR_REQUIREMENT_NOT_MET: () => 'Stratégie non évaluée : les données du canal ne fournissaient pas ce dont la stratégie a besoin.',
  ENGINE_CURRENCY_MISMATCH: (f) => `Stratégie non évaluée : autre devise que celle de l’offre (${f.raw('expected')}) pour ${f.value('source')}.`,
  DIVERGENCE_CASE_OPENED: (f) => `Dossier d’écart ouvert : le canal affichait un autre prix que ${f.money('expectedMinor')}, celui que nous attendons.`,
  // Отказ Gate у цены из данных конкурента: предложенная цена и отклонение выведены из цены конкурента [Р-85]; граница — наша
  BELOW_MIN_PRICE: (f) => `Rejeté : le prix proposé était sous votre prix minimum ${f.money('minMinor')}.`,
  BELOW_MARGIN_FLOOR: (f) => `Rejeté : le prix proposé était sous le plancher de marge ${f.money('floorMinor')}${opt(f, 'minMarginBp', () => ` (marge ${f.bp('minMarginBp')})`)}.`,
  ABOVE_MAX_PRICE: (f) => `Rejeté : le prix proposé dépassait votre prix maximum ${f.money('maxMinor')}.`,
  STEP_LIMIT: (f) => `Retenu : le changement depuis ${f.money('currentMinor')} dépassait le palier autorisé de ${f.bp('limitBp')}.`,
  INTERNAL_BOUND_VIOLATION: (f) => `Rejeté : erreur interne — ${f.value('check')} a trouvé le prix hors de ${f.money('floorMinor')}–${f.money('ceilingMinor')} ; une alerte a été levée.`,
};

